let Shader;
const Width=1112,Height=834;
let coolingMap;

function preload(){
  Shader=getShader(this._renderer);
}

function setup() {
  canv=createCanvas(Width,Height,WEBGL);
	pixelDensity(1);
  noStroke();
	coolingMap=createGraphics(width,height);
	coolingMap.loadPixels();
	for (let y=0;y<height;y++) {
		for (let x=0;x<width;x++) {
			let n = noise(x/50,y/50);
      let val=pow(n,3)*255;
			coolingMap.pixels[(x+y*width)*4  ]=val;
			coolingMap.pixels[(x+y*width)*4+1]=val;
			coolingMap.pixels[(x+y*width)*4+2]=val;
			coolingMap.pixels[(x+y*width)*4+3]=255;
		}
	}
	coolingMap.updatePixels();
	tex=createGraphics(width,height);
	background(0);
}

let uprisingSpeed=2;
let utime=0;

function draw() {
 	shader(Shader);
	tex.image(canv,0,-uprisingSpeed,width,height);
	coolingMap.image(coolingMap,0,-uprisingSpeed,width,height);
	coolingMap.loadPixels();
	if (uprisingSpeed>0) {
		for (let y=height-uprisingSpeed;y<height;y++) {
			for (let x=0;x<width;x++) {
				var n = noise(x/50,(y+utime*uprisingSpeed)/50);
				var val=pow(n,3)*255;
				coolingMap.pixels[(x+y*width)*4  ]=val;
				coolingMap.pixels[(x+y*width)*4+1]=val;
				coolingMap.pixels[(x+y*width)*4+2]=val;
				coolingMap.pixels[(x+y*width)*4+3]=255;
			}
		}
	} else if (uprisingSpeed<0) {
		for (let y=-uprisingSpeed-1;y>=0;y--) {
			for (let x=0;x<width;x++) {
				var n = noise(x/50,(y+utime*uprisingSpeed)/50);
				var val=pow(n,3)*255;
				coolingMap.pixels[(x+y*width)*4  ]=val;
				coolingMap.pixels[(x+y*width)*4+1]=val;
				coolingMap.pixels[(x+y*width)*4+2]=val;
				coolingMap.pixels[(x+y*width)*4+3]=255;
			}
		}
	}
	coolingMap.updatePixels();
	Shader.setUniform('tex',tex);
	Shader.setUniform('coolingMap',coolingMap);
	background(0);
  rect(0,0,width,height);
	image(coolingMap,0,0,width,height);
	if (uprisingSpeed!=0) {utime++;} 
}
function keyPressed() {
	if (keyCode==38&&uprisingSpeed<4) {utime*=uprisingSpeed==0?1:uprisingSpeed;uprisingSpeed+=1;utime/=uprisingSpeed==0?1:uprisingSpeed;}
	if (keyCode==40&&uprisingSpeed>-4) {utime*=uprisingSpeed==0?1:uprisingSpeed;uprisingSpeed-=1;utime/=uprisingSpeed==0?1:uprisingSpeed;}
}
function getShader(_renderer) {
	const vert=`
		precision highp float;
		attribute vec3 aPosition;
		attribute vec2 aTexCoord;
		varying vec2 vTexCoord;
		void main() {
			vTexCoord=aTexCoord;
			vec4 positionVec4=vec4(aPosition,1.);
			positionVec4.xy=positionVec4.xy*2.-1.; 
			gl_Position=positionVec4;
		}
	`;
	const frag=`
		precision highp float;
		varying vec2 vTexCoord;
		const float width=${windowWidth}.;
		const float height=${windowHeight}.;
		uniform sampler2D tex;
		uniform sampler2D coolingMap;
		float deltay=1.;
		float rem(float x, float y) {
			x=abs(x); 
			y=abs(y);
			for(int i=0;i>-1;i+=0) {
					if(x<y) {break;}
					x-=y;
			}
			return x;
		}
		float sq(float x) {
			return pow(x,2.);
		}
		void main() {
			float x=vTexCoord.x*width;
			float y=height-vTexCoord.y*height;
			float val=(
			//texture2D(tex,vec2(x/width,y/height)).r+
			texture2D(tex,vec2(x/width,(y-1.)/height)).r+
			texture2D(tex,vec2((x+1.)/width,y/height)).r+
			texture2D(tex,vec2(x/width,(y+1.)/height)).r+
			texture2D(tex,vec2((x-1.)/width,y/height)).r
			)/4.;
			val-=texture2D(coolingMap,vec2(x/width,rem(y/height,1.))).r/5.;
			//if (y>height-2.) {val=1.;}
			float arg=sqrt(sq(x-width/2.)+sq(y-height/2.));
			//float arg=sqrt(sq(x-width/2.-150.)+sq(y-height/2.))+sqrt(sq(x-width/2.+150.)+sq(y-height/2.));
			if (arg>height/4.&&arg<height/4.+5.) {val=1.;}
			gl_FragColor=vec4(vec3(val,(val-0.3),(val-0.6)),1.);
		}
	`;
	return createShader(vert, frag);
}

